#!/usr/bin/env bash
# coord-managed-hook
# Generated by `coord install` into an AGENT CLONE's .git/hooks/. Never tracked,
# never written into a product's default branch: a human clone of the same
# remote has no coordination hooks at all and is unaffected by coordination.
#
# This file carries no policy. The hook bodies live in the coordination install
# at $installRoot/githooks/, so upgrading coordination upgrades every clone and
# the shim never needs regenerating.
#
# It fails closed on purpose. A missing install root must block loudly; the one
# outcome this design refuses is an agent that keeps committing with every gate
# silently switched off.
set -euo pipefail

hook="$(basename "$0")"
hook_dir="$(cd "$(dirname "$0")" && pwd)"
original="$hook_dir/$hook.coord-original"
install_root="$(git config --local --get coord.installRoot 2>/dev/null || true)"

if [[ -z "$install_root" ]]; then
  echo "HOOK BLOCKED: coord.installRoot is unset in this clone, so the coordination hook bodies cannot be located." >&2
  echo "  This clone has coordination hooks installed, so it is an agent clone and must not commit without running the project's declared checks." >&2
  echo "  Fix: coord install --product <product> --coord-runtime <runtime> --agents <agents>" >&2
  echo "  Or remove the wiring entirely: coord uninstall --product <product> --coord-runtime <runtime>" >&2
  exit 1
fi

body="$install_root/githooks/$hook"

if [[ ! -x "$body" ]]; then
  echo "HOOK BLOCKED: coord.installRoot points at '$install_root', which has no executable githooks/$hook." >&2
  echo "  The coordination install was moved, renamed, or partially built." >&2
  echo "  Fix: coord doctor --coord-runtime <runtime> --product <product>" >&2
  exit 1
fi

# Nothing was displaced when coordination was installed: the common case, and
# the one where the body should own stdin and the exit status directly.
if [[ ! -x "$original" ]]; then
  exec "$body" "$@"
fi

# A hook this clone already had was moved aside at install time. Run both, so
# that adding coordination's gates never removes the product's. Coordination
# runs first: if it refuses the operation, the product's hook is not consulted.
#
# pre-push receives its ref list on stdin, and stdin can only be consumed once,
# so it is buffered here and replayed to each. The buffer is a shell variable
# rather than a temporary file: a predictable path under $TMPDIR is a symlink
# target an attacker can pre-create.
coord_stdin=""
if [[ "$hook" == "pre-push" ]]; then
  coord_stdin="$(cat)"
fi

coord_run() {
  if [[ "$hook" != "pre-push" ]]; then
    "$1" "${@:2}" </dev/null
  elif [[ -z "$coord_stdin" ]]; then
    "$1" "${@:2}" </dev/null
  else
    printf '%s\n' "$coord_stdin" | "$1" "${@:2}"
  fi
}

coord_run "$body" "$@"
coord_run "$original" "$@"
